import { getTournamentPoints } from './getTournamentPoints.mjs';
import { getParticipants } from '../participants/getParticipants.mjs';
import { MISSING_TOURNAMENT_RECORD } from '../../constants/errorConditionConstants.mjs';
import { SUCCESS } from '../../constants/resultConstants.mjs';

function getTournamentPointAwards({ participantFilters, policyDefinitions, tournamentRecord, level, }) {
    if (!tournamentRecord)
        return { error: MISSING_TOURNAMENT_RECORD };
    const pointsResult = getTournamentPoints({
        participantFilters,
        policyDefinitions,
        tournamentRecord,
        level,
    });
    if (pointsResult.error)
        return pointsResult;
    const { personPoints = {}, pairPoints = {}, teamPoints = {} } = pointsResult;
    const tournamentId = tournamentRecord.tournamentId;
    const tournamentEndDate = tournamentRecord.endDate;
    const { tournamentSeriesId } = tournamentRecord;
    const series = tournamentSeriesId ? { tournamentSeriesId } : {};
    const { participants = [] } = getParticipants({ tournamentRecord });
    const personToParticipant = {};
    const participantLookup = {};
    for (const p of participants) {
        participantLookup[p.participantId] = {
            participantName: p.participantName ?? '',
            personId: p.person?.personId,
        };
        if (p.person?.personId) {
            personToParticipant[p.person.personId] = {
                participantId: p.participantId,
                participantName: p.participantName ?? '',
            };
        }
    }
    const pointAwards = [];
    for (const [personId, awards] of Object.entries(personPoints)) {
        const participant = personToParticipant[personId];
        for (const award of awards) {
            pointAwards.push({
                ...award,
                personId,
                participantId: participant?.participantId ?? award.participantId,
                participantName: participant?.participantName,
                tournamentId: award.tournamentId ?? tournamentId,
                endDate: award.endDate ?? tournamentEndDate,
                ...series,
            });
        }
    }
    for (const [participantId, awards] of Object.entries(pairPoints)) {
        const info = participantLookup[participantId];
        for (const award of awards) {
            pointAwards.push({
                ...award,
                participantId,
                participantName: info?.participantName,
                tournamentId: award.tournamentId ?? tournamentId,
                endDate: award.endDate ?? tournamentEndDate,
                ...series,
            });
        }
    }
    for (const [participantId, awards] of Object.entries(teamPoints)) {
        const info = participantLookup[participantId];
        for (const award of awards) {
            pointAwards.push({
                ...award,
                participantId,
                participantName: info?.participantName,
                tournamentId: award.tournamentId ?? tournamentId,
                endDate: award.endDate ?? tournamentEndDate,
                ...series,
            });
        }
    }
    return { pointAwards, ...SUCCESS };
}

export { getTournamentPointAwards };
