import { addMatchUpsNotice, deleteMatchUpsNotice, modifyMatchUpNotice } from '../notifications/drawNotifications.mjs';
import { generateCollectionMatchUps } from '../../helpers/drawTopology/templates/tieMatchUps.mjs';
import { checkRequiredParameters } from '../../helpers/parameters/checkRequiredParameters.mjs';
import { resolveTieFormat } from '../../query/hierarchical/tieFormats/resolveTieFormat.mjs';
import { removeOrphanedTieFormats } from './writeTieFormat.mjs';
import { resolveFromParameters } from '../../acquire/resolveFromParameters.mjs';
import { NOT_IMPLEMENTED, INVALID_MATCHUP, NOT_FOUND } from '../../constants/errorConditionConstants.mjs';
import { decorateResult } from '../../functions/global/decorateResult.mjs';
import { getMatchUpId } from '../../functions/global/extractors.mjs';
import { ERROR, MATCHUP_ID, TOURNAMENT_RECORD, MATCHUP, PARAM } from '../../constants/attributeConstants.mjs';
import { TO_BE_PLAYED } from '../../constants/matchUpStatusValues.mjs';
import { SUCCESS } from '../../constants/resultConstants.mjs';

function resetTieFormat(params) {
    const stack = 'resetTieFormat';
    const { drawDefinition, event, uuids } = params;
    const paramCheck = checkRequiredParameters(params, [{ [TOURNAMENT_RECORD]: true, [MATCHUP_ID]: true }], stack);
    if (paramCheck.error)
        return paramCheck;
    const resolutions = resolveFromParameters(params, [{ [PARAM]: MATCHUP }]);
    if (resolutions[ERROR])
        return resolutions;
    const tournamentId = params.tournamentRecord?.tournamentId;
    const { matchUp, structure } = resolutions?.matchUp ?? {};
    if (!matchUp?.tieMatchUps)
        return decorateResult({
            result: { error: INVALID_MATCHUP },
            info: 'Must be a TEAM matchUp',
            stack,
        });
    if (!matchUp.tieFormat && !matchUp.tieFormatId)
        return { ...SUCCESS };
    const localFormat = resolveTieFormat({ matchUp, structure, drawDefinition, event }).tieFormat;
    if (localFormat?.collectionDefinitions.some((definition) => definition.matchUpTypeOptions !== undefined))
        return { error: NOT_IMPLEMENTED, info: 'Reset choice selections explicitly with resetMatchUpTypeChoice' };
    const tieFormat = resolveTieFormat({
        structure,
        drawDefinition,
        event,
    })?.tieFormat;
    if (!tieFormat)
        return decorateResult({
            result: { error: NOT_FOUND },
            info: 'No inherited tieFormat',
            stack,
        });
    const deletedMatchUpIds = [];
    const collectionIds = [];
    const tieMatchUps = [];
    const newMatchUps = [];
    for (const collectionDefinition of tieFormat.collectionDefinitions) {
        const { matchUpCount, collectionId } = collectionDefinition;
        collectionIds.push(collectionId);
        const existingCollectionMatchUps = (matchUp.tieMatchUps ?? []).filter((matchUp) => matchUp.collectionId === collectionId);
        if (existingCollectionMatchUps.length > matchUpCount) {
            existingCollectionMatchUps.sort((a, b) => (a.matchUpStatus === TO_BE_PLAYED ? 1 : 0) - (b.matchUpStatus === TO_BE_PLAYED ? 1 : 0));
            tieMatchUps.push(...existingCollectionMatchUps.slice(0, matchUpCount));
            deletedMatchUpIds.push(...existingCollectionMatchUps.slice(3).map(getMatchUpId));
        }
        else {
            tieMatchUps.push(...existingCollectionMatchUps);
            if (existingCollectionMatchUps.length < matchUpCount) {
                const matchUpsLimit = matchUpCount - existingCollectionMatchUps.length;
                const matchUps = generateCollectionMatchUps({
                    collectionDefinition,
                    matchUpsLimit,
                    matchUp,
                    uuids,
                });
                newMatchUps.push(...matchUps);
            }
        }
    }
    for (const tieMatchUp of matchUp?.tieMatchUps ?? []) {
        if (tieMatchUp.collectionId && !collectionIds.includes(tieMatchUp.collectionId))
            deletedMatchUpIds.push(tieMatchUp.matchUpId);
    }
    if (newMatchUps.length) {
        tieMatchUps.push(...newMatchUps);
        addMatchUpsNotice({
            eventId: event?.eventId,
            matchUps: newMatchUps,
            drawDefinition,
            tournamentId,
        });
    }
    if (deletedMatchUpIds.length) {
        deleteMatchUpsNotice({
            matchUpIds: deletedMatchUpIds,
            eventId: event?.eventId,
            drawDefinition,
            tournamentId,
        });
    }
    if (matchUp) {
        matchUp.tieMatchUps = tieMatchUps;
        matchUp.tieFormatId = undefined;
        matchUp.tieFormat = undefined;
        if (event)
            removeOrphanedTieFormats({ event });
        modifyMatchUpNotice({
            structureId: structure?.structureId,
            eventId: event?.eventId,
            event,
            context: stack,
            drawDefinition,
            tournamentId,
            matchUp,
        });
    }
    return { ...SUCCESS, newMatchUps, deletedMatchUpIds };
}

export { resetTieFormat };
