import { removeMatchUpSideParticipant } from '../matchUps/sides/removeMatchUpSideParticipant.mjs';
import { checkRequiredParameters } from '../../helpers/parameters/checkRequiredParameters.mjs';
import { isMatchUpEventType } from '../../helpers/matchUpEventTypes/isMatchUpEventType.mjs';
import { resetMatchUpLineUps } from '../matchUps/lineUps/resetMatchUpLineUps.mjs';
import { setMatchUpStatus } from '../matchUps/matchUpStatus/setMatchUpStatus.mjs';
import { getAdHocStructureDetails } from './getAdHocStructureDetails.mjs';
import { toBePlayed } from '../../fixtures/scoring/outcomes/toBePlayed.mjs';
