function footprintCovers({ required, loaded, tournamentRecord }) {
    const has = (shard) => loaded.shards.includes(shard);
    if (loaded.tournament || has('tournament'))
        return [];
    if (required.shards.includes('tournament'))
        return ['tournament'];
    const recordDrawIds = new Set((tournamentRecord?.events ?? []).flatMap((event) => (event.drawDefinitions ?? []).map(({ drawId }) => drawId)));
    const loadedEventIds = new Set(has('eventDraws') ? (loaded.eventIds ?? []) : []);
    const participantDrawIds = new Set([
        ...(loaded.drawIds ?? []),
        ...(tournamentRecord?.events ?? [])
            .filter(({ eventId }) => loadedEventIds.has(eventId))
            .flatMap((event) => (event.drawDefinitions ?? []).map(({ drawId }) => drawId)),
    ]);
    const missing = [];
    const requiredDrawIds = required.drawIds ?? [];
    for (const shard of required.shards) {
        if (shard === 'shell')
            continue;
        if (shard === 'draw' && requiredDrawIds.every((drawId) => recordDrawIds.has(drawId)))
            continue;
        if (shard === 'eventDraws' && (required.eventIds ?? []).every((eventId) => loadedEventIds.has(eventId)))
            continue;
        if (shard === 'participants' && has('participants'))
            continue;
        if (shard === 'drawParticipants' &&
            (has('participants') ||
                (has('drawParticipants') && requiredDrawIds.every((drawId) => participantDrawIds.has(drawId)))))
            continue;
        missing.push(shard);
    }
    return missing;
}

export { footprintCovers };
