import { checkAndNotifyUnpublishTournament } from '../publishing/checkAndNotifyUnpublishTournament.mjs';
import { checkAndUpdateSchedulingProfile } from '../tournaments/schedulingProfile.mjs';
import { checkRequiredParameters } from '../../helpers/parameters/checkRequiredParameters.mjs';
import { isTournamentPublished } from '../../query/publishing/isTournamentPublished.mjs';
import { deleteEventsNotice } from '../notifications/eventNotifications.mjs';
import { deleteDrawNotice } from '../notifications/drawNotifications.mjs';
import { addTournamentTimeItem } from '../timeItems/addTimeItem.mjs';
import { hasTopic, addNotice } from '../../global/state/globalState.mjs';
import { UNPUBLISH_TOURNAMENT, DELETE_PARTICIPANTS, AUDIT } from '../../constants/topicConstants.mjs';
import { ARRAY, TOURNAMENT_RECORD, OF_TYPE } from '../../constants/attributeConstants.mjs';
import { UNGROUPED } from '../../constants/entryStatusValues.mjs';
import { DELETE_EVENTS } from '../../constants/auditConstants.mjs';
import { SUCCESS } from '../../constants/resultConstants.mjs';
import { DOUBLES } from '../../constants/eventConstants.mjs';

function deleteEvents(params) {
    const paramCheck = checkRequiredParameters(params, [
        { [TOURNAMENT_RECORD]: true },
        { eventIds: true, [OF_TYPE]: ARRAY },
    ]);
    if (paramCheck.error)
        return paramCheck;
    const { removePairParticipants, tournamentRecord, eventIds } = params;
    const wasTournamentPublished = hasTopic(UNPUBLISH_TOURNAMENT) && isTournamentPublished(tournamentRecord);
    const auditTrail = [];
    const deletedEventDetails = [];
    const deletedEventIds = [];
    const deletedDrawIds = [];
    const activePairParticipantIds = [];
    const pairParticipantIds = [];
    tournamentRecord.events = (tournamentRecord.events ?? []).filter((event) => {
        if (eventIds.includes(event.eventId)) {
            const auditData = {
                action: DELETE_EVENTS,
                payload: { events: [event] },
            };
            auditTrail.push(auditData);
            deletedEventDetails.push({
                tournamentId: tournamentRecord.tournamentId,
                eventName: event.eventName,
                eventType: event.eventType,
                category: event.category,
                eventId: event.eventId,
                gender: event.gender,
            });
        }
        const enteredPairParticipantIds = event.eventType === DOUBLES
            ? (event.entries ?? [])
                .map(({ entryStatus, participantId }) => entryStatus !== UNGROUPED && participantId)
                .filter(Boolean)
            : [];
        const deleteEvent = eventIds.includes(event.eventId);
        if (deleteEvent) {
            pairParticipantIds.push(...enteredPairParticipantIds);
            deletedEventIds.push(event.eventId);
            deletedDrawIds.push(...(event.drawDefinitions ?? []).map((drawDefinition) => drawDefinition.drawId));
        }
        else {
            activePairParticipantIds.push(...enteredPairParticipantIds);
        }
        return !deleteEvent;
    });
    const removedParticipantIds = [];
    if (removePairParticipants) {
        const particiapntIdsToRemove = new Set(pairParticipantIds.filter((participantId) => !activePairParticipantIds.includes(participantId)));
        removedParticipantIds.push(...particiapntIdsToRemove);
        tournamentRecord.participants = tournamentRecord.participants.filter(({ participantId }) => !particiapntIdsToRemove.has(participantId));
    }
    checkAndUpdateSchedulingProfile({ tournamentRecord });
    if (deletedEventIds.length) {
        const tournamentId = tournamentRecord.tournamentId;
        deleteEventsNotice({ tournamentId, eventIds: deletedEventIds });
        for (const drawId of deletedDrawIds)
            deleteDrawNotice({ tournamentId, drawId });
        if (removedParticipantIds.length) {
            addNotice({ topic: DELETE_PARTICIPANTS, payload: { tournamentId, participantIds: removedParticipantIds } });
        }
        if (wasTournamentPublished)
            checkAndNotifyUnpublishTournament({ tournamentRecord });
    }
    if (auditTrail.length) {
        if (hasTopic(AUDIT)) {
            const tournamentId = tournamentRecord.tournamentId;
            addNotice({ topic: AUDIT, payload: { type: DELETE_EVENTS, tournamentId, detail: auditTrail } });
        }
        else {
            const timeItem = {
                itemValue: deletedEventDetails,
                itemType: DELETE_EVENTS,
            };
            addTournamentTimeItem({ tournamentRecord, timeItem });
        }
    }
    return { ...SUCCESS };
}

export { deleteEvents };
